   183  int _vcardparameter_string_to_enum(const char *str, vcardparameter_kind kind)
   184  {
   185      int i, num_params;
   186
   187      icalerror_check_arg_rz(str != 0, "str");
   188
   189      num_params = (int)(sizeof(vcardparameter_map) / sizeof(vcardparameter_map[0]));
   190      for (i = 0; i < num_params; i++) {
   191          if (kind == VCARD_ANY_PARAMETER || (kind == vcardparameter_map[i].kind)) {
   192              if (strcasecmp(str, vcardparameter_map[i].str) == 0) {
   193                  return vcardparameter_map[i].enumeration;
   194              }
   195          }
   196      }
   197
   198      return 0;
   199  }
